H.background();
const W = H.W, Ht = H.H;
const x0 = 120, x1 = 780;
const yBase = 380;
const Ea = 140;
const dH = P.dH;
const Ereact = 0;
const Eprod = -dH;
const yOf = e => yBase - e;
const exo = dH > 0;
H.text("Reaction energy diagram:  dH = H_products - H_reactants", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text(exo ? "Exothermic: releases heat, dH < 0, products LOWER" : (dH < 0 ? "Endothermic: absorbs heat, dH > 0, products HIGHER" : "Thermoneutral: dH = 0"), 24, 52, { color: H.colors.sub, size: 13 });
const xPeak = (x0 + x1) / 2;
const yPeak = yOf(Ea);
const pts = [];
for (let i = 0; i <= 60; i++) {
  const f = i / 60;
  const xx = x0 + (x1 - x0) * f;
  let yy;
  if (f < 0.5) {
    const g = f / 0.5;
    const e = Ereact + (Ea - Ereact) * (g * g * (3 - 2 * g));
    yy = yOf(e);
  } else {
    const g = (f - 0.5) / 0.5;
    const e = Ea + (Eprod - Ea) * (g * g * (3 - 2 * g));
    yy = yOf(e);
  }
  pts.push([xx, yy]);
}
H.path(pts, { color: H.colors.accent, width: 3 });
H.line(x0, yOf(Ereact), x0 + 70, yOf(Ereact), { color: H.colors.sub, width: 2 });
H.line(x1 - 70, yOf(Eprod), x1, yOf(Eprod), { color: H.colors.sub, width: 2 });
H.text("reactants", x0, yOf(Ereact) - 10, { color: H.colors.sub, size: 12 });
H.text("products", x1 - 70, yOf(Eprod) + (Eprod < Ereact ? 18 : -10), { color: H.colors.sub, size: 12 });
H.line(x0 - 30, yBase, x0 - 30, yBase - 320, { color: H.colors.axis, width: 2 });
H.text("Energy", x0 - 60, yBase - 330, { color: H.colors.sub, size: 12 });
const arrowCol = exo ? H.colors.good : H.colors.warn;
H.arrow(x1 - 35, yOf(Ereact), x1 - 35, yOf(Eprod), { color: arrowCol, width: 2 });
H.text("dH = " + (Eprod - Ereact).toFixed(0) + " kJ", x1 - 30, (yOf(Ereact) + yOf(Eprod)) / 2, { color: arrowCol, size: 13, weight: 700 });
const prog = 0.5 + 0.5 * Math.sin(t * 0.8);
const idx = Math.min(60, Math.floor(prog * 60));
H.circle(pts[idx][0], pts[idx][1], 8, { fill: H.colors.accent2 });
H.text("Ea(fwd) = " + Ea + " kJ", xPeak - 50, yPeak - 16, { color: H.colors.violet, size: 12 });
